            dfs(i, -1)
    return sorted(bridges)

def strongly_connected_components(graph):
    index_counter = [0]
    stack = []
    lowlink = {}
    index = {}
    on_stack = {}
    result = []
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        for n in neighbors:
            all_nodes.add(n)
    def strongconnect(v):
        index[v] = index_counter[0]
        lowlink[v] = index_counter[0]
        index_counter[0] += 1
        on_stack[v] = True
        stack.append(v)
        for w in graph.get(v, []):
            if w not in index:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack.get(w, False):
                lowlink[v] = min(lowlink[v], index[w])
        if lowlink[v] == index[v]:
            component = set()
            while True:
                w = stack.pop()
                on_stack[w] = False
                component.add(w)
                if w == v:
                    break
            result.append(component)
    for v in all_nodes:
        if v not in index:
            strongconnect(v)
    return result

