    return max_area

def median_of_two_sorted(nums1, nums2):
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1
    m, n = len(nums1), len(nums2)
    if m == 0:
        mid = n // 2
        if n % 2 == 1:
            return float(nums2[mid])
        return (nums2[mid-1] + nums2[mid]) / 2.0
    lo, hi = 0, m
    while lo <= hi:
        i = (lo + hi) // 2
        j = (m + n + 1) // 2 - i
        left1 = nums1[i-1] if i > 0 else float('-inf')
        right1 = nums1[i] if i < m else float('inf')
        left2 = nums2[j-1] if j > 0 else float('-inf')
        right2 = nums2[j] if j < n else float('inf')
        if left1 <= right2 and left2 <= right1:
            if (m + n) % 2 == 1:
                return float(max(left1, left2))
            return (max(left1, left2) + min(right1, right2)) / 2.0
        elif left1 > right2:
            hi = i - 1
        else:
            lo = i + 1
    return 0.0

def count_smaller_after_self(nums):
    if not nums:
        return []
    n = len(nums)
    result = [0] * n
    def merge_sort(enum):
        half = len(enum) // 2
        if half:
            left, right = merge_sort(enum[:half]), merge_sort(enum[half:])
            for i in range(len(enum))[::-1]:
                if not right or (left and left[-1][1] > right[-1][1]):
                    result[left[-1][0]] += len(right)
                    enum[i] = left.pop()
                else:
                    enum[i] = right.pop()
        return enum
    merge_sort(list(enumerate(nums)))
    return result

def calculate_expression(s):
    def parse(tokens, pos):
        return parse_expr(tokens, pos)
    def parse_expr(tokens, pos):
        val, pos = parse_term(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_term(tokens, pos)
            if op == '+': val += right
            else: val -= right
        return val, pos
    def parse_term(tokens, pos):
        val, pos = parse_factor(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right, pos = parse_factor(tokens, pos)
            if op == '*': val *= right
            else: val = int(val / right)
        return val, pos
    def parse_factor(tokens, pos):
        if tokens[pos] == '(':
            pos += 1
            val, pos = parse_expr(tokens, pos)
            pos += 1  # skip ')'
            return val, pos
        if tokens[pos] == '-':
            pos += 1
            val, pos = parse_factor(tokens, pos)
            return -val, pos
        return int(tokens[pos]), pos + 1
    tokens = []
    i = 0
    s = s.replace(' ', '')
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(s[i:j])
            i = j
        else:
            tokens.append(s[i])
            i += 1
    result, _ = parse(tokens, 0)
    return result

def word_break_all(s, word_dict):
    word_set = set(word_dict)
    memo = {}
    def backtrack(start):
        if start in memo:
            return memo[start]
        if start == len(s):
            return [[]]
        results = []
        for end in range(start + 1, len(s) + 1):
            word = s[start:end]
            if word in word_set:
                for rest in backtrack(end):
                    results.append([word] + rest)
        memo[start] = results
        return results
    return [' '.join(words) for words in backtrack(0)]

def alien_dictionary(words):
    from collections import defaultdict, deque
    adj = defaultdict(set)
    in_degree = {c: 0 for word in words for c in word}
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i+1]
        min_len = min(len(w1), len(w2))
        if len(w1) > len(w2) and w1[:min_len] == w2[:min_len]:
            return ''
        for j in range(min_len):
            if w1[j] != w2[j]:
                if w2[j] not in adj[w1[j]]:
                    adj[w1[j]].add(w2[j])
                    in_degree[w2[j]] += 1
                break
    queue = deque([c for c in in_degree if in_degree[c] == 0])
    result = []
    while queue:
        c = queue.popleft()
        result.append(c)
        for neighbor in adj[c]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
    if len(result) != len(in_degree):
        return ''
    return ''.join(result)

def longest_substring_k_distinct(s, k):
    if k == 0 or not s:
        return 0
    from collections import defaultdict
    char_count = defaultdict(int)
    left = 0
    max_len = 0
    for right in range(len(s)):
        char_count[s[right]] += 1
        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1
        max_len = max(max_len, right - left + 1)
    return max_len

def min_window_substring(s, t):
    if not t or not s:
        return ''
    from collections import Counter
    dict_t = Counter(t)
    required = len(dict_t)
    formed = 0
    window_counts = {}
    ans = (float('inf'), None, None)
    left = 0
    for right in range(len(s)):
        ch = s[right]
        window_counts[ch] = window_counts.get(ch, 0) + 1
        if ch in dict_t and window_counts[ch] == dict_t[ch]:
            formed += 1
        while left <= right and formed == required:
            if right - left + 1 < ans[0]:
                ans = (right - left + 1, left, right)
            ch = s[left]
            window_counts[ch] -= 1
            if ch in dict_t and window_counts[ch] < dict_t[ch]:
                formed -= 1
            left += 1
    return '' if ans[0] == float('inf') else s[ans[1]:ans[2]+1]

def maximal_rectangle(matrix):
    if not matrix or not matrix[0]:
        return 0
    n = len(matrix[0])
    heights = [0] * (n + 1)
    max_area = 0
    for row in matrix:
        for i in range(n):
            heights[i] = heights[i] + 1 if row[i] == '1' else 0
        stack = [-1]
        for i in range(n + 1):
            while stack[-1] != -1 and heights[stack[-1]] >= heights[i]:
                h = heights[stack.pop()]
                w = i - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(i)
    return max_area

def ntt_multiply(a, b):
    if not a or not b:
        return []
    result_len = len(a) + len(b) - 1
    result = [0] * result_len
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            result[i + j] += x * y
    return result

def solve_linear_system(A, b):
    n = len(A)
    aug = [row[:] + [b[i]] for i, row in enumerate(A)]
    for col in range(n):
        max_row = max(range(col, n), key=lambda r: abs(aug[r][col]))
        aug[col], aug[max_row] = aug[max_row], aug[col]
        if abs(aug[col][col]) < 1e-12:
            return None
        for row in range(col + 1, n):
            factor = aug[row][col] / aug[col][col]
            for j in range(col, n + 1):
                aug[row][j] -= factor * aug[col][j]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        x[i] = aug[i][n]
        for j in range(i + 1, n):
            x[i] -= aug[i][j] * x[j]
        x[i] /= aug[i][i]
    return [round(v, 6) for v in x]

def convex_hull_trick(lines, queries):
    if not lines or not queries:
        return []
    results = []
    for x in queries:
        min_y = float('inf')
        for m, c in lines:
            min_y = min(min_y, m * x + c)
        results.append(min_y)
    return results

def matrix_chain_order(p):
    n = len(p) - 1
    if n <= 0:
        return 0
    dp = [[0]*n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i, j):
                cost = dp[i][k] + dp[k+1][j] + p[i]*p[k+1]*p[j+1]
                dp[i][j] = min(dp[i][j], cost)
    return dp[0][n-1]

class lru_cache_ttl:
    def __init__(self, capacity, ttl_seconds):
        self.capacity = capacity
        self.ttl = ttl_seconds
        self.cache = {}
        self.order = []
    def _evict_expired(self, current_time):
        expired = [k for k in self.cache if current_time - self.cache[k][1] >= self.ttl]
        for k in expired:
            del self.cache[k]
            if k in self.order:
                self.order.remove(k)
    def _touch(self, key):
        if key in self.order:
            self.order.remove(key)
        self.order.append(key)
    def get(self, key, current_time):
        self._evict_expired(current_time)
        if key not in self.cache:
            return -1
        self._touch(key)
        return self.cache[key][0]
    def put(self, key, value, current_time):
        self._evict_expired(current_time)
        if key in self.cache:
            self._touch(key)
        else:
            if len(self.cache) >= self.capacity:
                oldest = self.order.pop(0)
                del self.cache[oldest]
            self.order.append(key)
        self.cache[key] = (value, current_time)

class consistent_hash_ring:
    def __init__(self, nodes, replicas=100):
        import hashlib, bisect
        self.replicas = replicas
        self.ring = {}
        self.sorted_keys = []
        self._hashlib = hashlib
        self._bisect = bisect
        for node in nodes:
            self.add_node(node)
    def _hash(self, key):
        return int(self._hashlib.md5(key.encode()).hexdigest(), 16)
    def add_node(self, node):
        for i in range(self.replicas):
            h = self._hash(f'{node}:{i}')
            self.ring[h] = node
            self._bisect.insort(self.sorted_keys, h)
    def remove_node(self, node):
        for i in range(self.replicas):
            h = self._hash(f'{node}:{i}')
            if h in self.ring:
                del self.ring[h]
                self.sorted_keys.remove(h)
    def get_node(self, key):
        if not self.ring:
            return None
        h = self._hash(key)
        idx = self._bisect.bisect(self.sorted_keys, h)
        if idx == len(self.sorted_keys):
            idx = 0
        return self.ring[self.sorted_keys[idx]]

class skiplist_contains:
    def __init__(self, max_level=16, p=0.5):
        import random
        self._random = random
        self.max_level = max_level
        self.p = p
        self.head = {'val': float('-inf'), 'next': [None] * max_level}
        self.level = 0
    def _random_level(self):
        lvl = 0
        while self._random.random() < self.p and lvl < self.max_level - 1:
            lvl += 1
        return lvl
    def search(self, val):
        current = self.head
        for i in range(self.level, -1, -1):
            while current['next'][i] and current['next'][i]['val'] < val:
                current = current['next'][i]
        current = current['next'][0]
        return current is not None and current['val'] == val
    def insert(self, val):
        update = [None] * self.max_level
        current = self.head
        for i in range(self.level, -1, -1):
            while current['next'][i] and current['next'][i]['val'] < val:
                current = current['next'][i]
            update[i] = current
        new_level = self._random_level()
        if new_level > self.level:
            for i in range(self.level + 1, new_level + 1):
                update[i] = self.head
            self.level = new_level
        new_node = {'val': val, 'next': [None] * (new_level + 1)}
        for i in range(new_level + 1):
            new_node['next'][i] = update[i]['next'][i]
            update[i]['next'][i] = new_node
    def delete(self, val):
        update = [None] * self.max_level
        current = self.head
        for i in range(self.level, -1, -1):
            while current['next'][i] and current['next'][i]['val'] < val:
                current = current['next'][i]
            update[i] = current
        target = current['next'][0]
        if target is None or target['val'] != val:
            return False
        for i in range(self.level + 1):
            if update[i]['next'][i] != target:
                break
            update[i]['next'][i] = target['next'][i]
        while self.level > 0 and self.head['next'][self.level] is None:
            self.level -= 1
        return True

class bloom_filter:
    def __init__(self, size, num_hashes):
        self.size = size
        self.num_hashes = num_hashes
        self.bits = [False] * size
    def _hashes(self, item):
        import hashlib
        results = []
        for i in range(self.num_hashes):
            h = int(hashlib.sha256(f'{item}_{i}'.encode()).hexdigest(), 16)
            results.append(h % self.size)
        return results
    def add(self, item):
        for h in self._hashes(item):
            self.bits[h] = True
    def might_contain(self, item):
        return all(self.bits[h] for h in self._hashes(item))

def cron_parser(expr):
    fields = expr.strip().split()
    ranges_map = {
        'minute': (0, 59),
        'hour': (0, 23),
        'day': (1, 31),
        'month': (1, 12),
        'weekday': (0, 6)
    }
    keys = ['minute', 'hour', 'day', 'month', 'weekday']
    def parse_field(field, lo, hi):
        result = set()
        for part in field.split(','):
            step = 1
            if '/' in part:
                range_part, step = part.split('/')
                step = int(step)
            else:
                range_part = part
            if range_part == '*':
                start, end = lo, hi
            elif '-' in range_part:
                s, e = range_part.split('-')
                start, end = int(s), int(e)
            else:
                start = end = int(range_part)
            for v in range(start, end + 1, step):
                if lo <= v <= hi:
                    result.add(v)
        return sorted(result)
    res = {}
    for i, key in enumerate(keys):
        lo, hi = ranges_map[key]
        res[key] = parse_field(fields[i], lo, hi)
    return res
